package com.luci.pianoroom;
import java.io.*;
/** Neutral defaults preserve existing mixes; each scene owns four settings. */
public final class ChannelSettings {
 public boolean hybrid,releaseSmooth,harmonics;public int spaceRoom,ambience=35,texture,ducking,spaceDecay=35,repetition,soundPreset=-1;
 public int pan,chorus,delay,delayMs=280,feedback=30,reverb=100,resonance,low,mid,high;public boolean pedal,contextual,bankProfile;public boolean bodyEnabled;public int bodyAmount,boardAmount,bodySize=50,boardDamping=50,lid=100;public int blend,blendCurve,hammer,keyNoise,pedalNoise;
 public ChannelSettings copy(){ChannelSettings c=new ChannelSettings();c.pan=pan;c.chorus=chorus;c.delay=delay;c.delayMs=delayMs;c.feedback=feedback;c.reverb=reverb;c.resonance=resonance;c.low=low;c.mid=mid;c.high=high;c.pedal=pedal;c.contextual=contextual;c.bankProfile=bankProfile;c.blend=blend;c.blendCurve=blendCurve;c.hammer=hammer;c.keyNoise=keyNoise;c.pedalNoise=pedalNoise;c.bodyEnabled=bodyEnabled;c.bodyAmount=bodyAmount;c.boardAmount=boardAmount;c.bodySize=bodySize;c.boardDamping=boardDamping;c.lid=lid;c.hybrid=hybrid;c.spaceRoom=spaceRoom;c.ambience=ambience;c.texture=texture;c.ducking=ducking;c.spaceDecay=spaceDecay;c.repetition=repetition;c.releaseSmooth=releaseSmooth;c.harmonics=harmonics;c.soundPreset=soundPreset;return c;}
 public void writeSpace(DataOutputStream o)throws IOException{o.writeBoolean(hybrid);o.writeInt(spaceRoom);o.writeInt(ambience);o.writeInt(texture);o.writeInt(ducking);o.writeInt(spaceDecay);o.writeInt(repetition);o.writeBoolean(releaseSmooth);o.writeBoolean(harmonics);o.writeInt(soundPreset);}
 public void readSpace(DataInputStream i)throws IOException{hybrid=i.readBoolean();spaceRoom=i.readInt();ambience=i.readInt();texture=i.readInt();ducking=i.readInt();spaceDecay=i.readInt();repetition=i.readInt();releaseSmooth=i.readBoolean();harmonics=i.readBoolean();soundPreset=i.readInt();if(spaceRoom<0||spaceRoom>2||ambience<0||ambience>100||texture<0||texture>100||ducking<0||ducking>100||spaceDecay<0||spaceDecay>100||repetition<0||repetition>100||soundPreset< -1||soundPreset>5)throw new IOException("Ambiente de canal inválido");}
 public void writeBody(DataOutputStream o)throws IOException{o.writeBoolean(bodyEnabled);o.writeInt(bodyAmount);o.writeInt(boardAmount);o.writeInt(bodySize);o.writeInt(boardDamping);o.writeInt(lid);}
 public void readBody(DataInputStream i)throws IOException{bodyEnabled=i.readBoolean();bodyAmount=i.readInt();boardAmount=i.readInt();bodySize=i.readInt();boardDamping=i.readInt();lid=i.readInt();if(bodyAmount<0||bodyAmount>100||boardAmount<0||boardAmount>100||bodySize<0||bodySize>100||boardDamping<0||boardDamping>100||lid<0||lid>100)throw new IOException("Corpo/tábua inválidos");}
 public void writePiano(DataOutputStream o)throws IOException{o.writeInt(blend);o.writeInt(blendCurve);o.writeBoolean(contextual);o.writeBoolean(bankProfile);o.writeInt(hammer);o.writeInt(keyNoise);o.writeInt(pedalNoise);}
 public void readPiano(DataInputStream i)throws IOException{blend=i.readInt();blendCurve=i.readInt();contextual=i.readBoolean();bankProfile=i.readBoolean();hammer=i.readInt();keyNoise=i.readInt();pedalNoise=i.readInt();if(blend<0||blend>8||blendCurve<0||blendCurve>1||hammer<0||hammer>100||keyNoise<0||keyNoise>100||pedalNoise<0||pedalNoise>100)throw new IOException("Realismo de piano inválido");}
 public void write(DataOutputStream o)throws IOException{o.writeInt(pan);o.writeInt(chorus);o.writeInt(delay);o.writeInt(delayMs);o.writeInt(feedback);o.writeInt(reverb);o.writeInt(resonance);o.writeInt(low);o.writeInt(mid);o.writeInt(high);o.writeBoolean(pedal);}
 public static ChannelSettings read(DataInputStream i)throws IOException{ChannelSettings c=new ChannelSettings();c.pan=i.readInt();c.chorus=i.readInt();c.delay=i.readInt();c.delayMs=i.readInt();c.feedback=i.readInt();c.reverb=i.readInt();c.resonance=i.readInt();c.low=i.readInt();c.mid=i.readInt();c.high=i.readInt();c.pedal=i.readBoolean();if(c.pan< -100||c.pan>100||c.chorus<0||c.chorus>100||c.delay<0||c.delay>60||c.delayMs<40||c.delayMs>500||c.feedback<0||c.feedback>65||c.reverb<0||c.reverb>150||c.resonance<0||c.resonance>100||c.low< -6||c.low>6||c.mid< -6||c.mid>6||c.high< -6||c.high>6)throw new IOException("Efeitos de canal inválidos");return c;}
}
